import * as THREE from 'three'
import { useEffect, useMemo, useRef, useState } from 'react'
import { Canvas, useFrame, useThree } from '@react-three/fiber'

const heroTarget = new THREE.Vector3()
const cameraTarget = new THREE.Vector3()
const lookAtTarget = new THREE.Vector3()
const poreScale = new THREE.Vector3(1, 1, 1)
const _up = new THREE.Vector3(0, 1, 0)
const _dir = new THREE.Vector3()
const _quat = new THREE.Quaternion()

const ATOM_AQUA = '#7ec8c8'
const ATOM_LIME = '#b8d66a'
const ATOM_BLUE = '#6eb4d8'
const BOND = '#9ad4d0'

const clamp = (value, min = 0, max = 1) => Math.min(Math.max(value, min), max)
const smooth = (start, end, value) => {
  const normalized = clamp((value - start) / (end - start))
  return normalized * normalized * (3 - 2 * normalized)
}
const lerp = THREE.MathUtils.lerp

const BEATS = {
  focusStart: 0.08,
  focusEnd: 0.32,
  poreInStart: 0.28,
  poreInEnd: 0.4,
  transitStart: 0.4,
  transitEnd: 0.68,
  clearStart: 0.55,
  clearEnd: 0.72,
  poreOutStart: 0.68,
  poreOutEnd: 0.8,
  brandStart: 0.78,
  brandEnd: 0.92,
}

function seededRandom(seed) {
  const x = Math.sin(seed * 127.1 + 311.7) * 43758.5453
  return x - Math.floor(x)
}

function makeFieldLayout(count) {
  const items = []
  for (let i = 0; i < count; i += 1) {
    const r0 = seededRandom(i + 1)
    const r1 = seededRandom(i + 17)
    const r2 = seededRandom(i + 41)
    const r3 = seededRandom(i + 73)
    const r4 = seededRandom(i + 99)
    items.push({
      position: [(r0 - 0.5) * 14, 0.6 + r1 * 4.5, (r2 - 0.5) * 10 - 1],
      rotation: [r3 * Math.PI, r4 * Math.PI, r0 * Math.PI],
      scale: 0.45 + r1 * 0.55,
      drift: 0.4 + r2 * 0.8,
      phase: r3 * Math.PI * 2,
      palette: i % 3,
    })
  }
  return items
}

function bondQuaternion(dirArr) {
  _dir.set(dirArr[0], dirArr[1], dirArr[2]).normalize()
  _quat.setFromUnitVectors(_up, _dir)
  return _quat.clone()
}

export default function App() {
  const [progress, setProgress] = useState(0)

  useEffect(() => {
    const update = () => {
      const scrollable = document.documentElement.scrollHeight - window.innerHeight
      setProgress(scrollable > 0 ? clamp(window.scrollY / scrollable) : 0)
    }
    update()
    window.addEventListener('scroll', update, { passive: true })
    window.addEventListener('resize', update)
    return () => {
      window.removeEventListener('scroll', update)
      window.removeEventListener('resize', update)
    }
  }, [])

  const brandOpacity = smooth(BEATS.brandStart, BEATS.brandEnd, progress)
  const hintOpacity = 1 - smooth(0.02, 0.12, progress)

  return (
    <main className="experience-shell">
      <div className="canvas-stage">
        <Canvas
          dpr={[1, 1.5]}
          camera={{ position: [0, 0.4, 11], fov: 36, near: 0.1, far: 60 }}
          gl={{ antialias: true, alpha: false, preserveDrawingBuffer: true }}>
          <color attach="background" args={['#0a3d45']} />
          <fog attach="fog" args={['#0a3d45', 14, 34]} />
          <ambientLight intensity={0.85} color="#d8fff5" />
          <directionalLight position={[5, 8, 6]} intensity={2.2} color="#ffffff" />
          <directionalLight position={[-6, -2, 4]} intensity={0.9} color="#6ec8d8" />
          <pointLight position={[0, 2, 5]} intensity={1.4} color="#a8ffe8" />
          <CameraRig progress={progress} />
          <MicroParticles progress={progress} />
          <FieldMolecules progress={progress} />
          <HeroMolecule progress={progress} />
          <Nanopore progress={progress} />
        </Canvas>

        <div className="scroll-hint" style={{ opacity: hintOpacity }}>
          Scroll to follow the molecule
        </div>

        <div className="brand-reveal" style={{ opacity: brandOpacity }}>
          <div className="brand-name">
            AAGAMI
            <span>
              SE
              <span className="brand-q">
                Q
                <i className="brand-q-dot" aria-hidden />
              </span>
            </span>
          </div>
          <p className="brand-tagline">Clarity in the fight against cancer</p>
        </div>
      </div>
      <div className="scroll-space" aria-hidden />
    </main>
  )
}

function CameraRig({ progress }) {
  const { camera } = useThree()

  useFrame((_, delta) => {
    const focus = smooth(BEATS.focusStart, BEATS.focusEnd, progress)
    const transit = smooth(BEATS.transitStart, BEATS.transitEnd, progress)
    const brand = smooth(BEATS.brandStart, BEATS.brandEnd, progress)

    // Angle down slightly during transit so the membrane reads as a horizontal sheet
    const camY = lerp(0.55, 2.4, transit) * (1 - brand * 0.85) + lerp(0.4, 0.2, brand)
    const camZ = lerp(11, 8.2, focus)
    const throughZ = lerp(camZ, 7.4, transit)
    const finalZ = lerp(throughZ, 6.4, brand)

    cameraTarget.set(lerp(0.35, 0, focus) * (1 - brand), camY, finalZ)
    lookAtTarget.set(0, lerp(0.8, -0.4, transit) * (1 - brand * 0.7), 0)

    camera.position.lerp(cameraTarget, 1 - Math.exp(-delta * 4.5))
    camera.lookAt(lookAtTarget)
    camera.fov = lerp(36, 30, focus)
    camera.updateProjectionMatrix()
  })

  return null
}

function AtomMaterial({ color, emissiveIntensity = 0.35 }) {
  return (
    <meshStandardMaterial color={color} emissive={color} emissiveIntensity={emissiveIntensity} metalness={0.15} roughness={0.25} />
  )
}

function MoleculeMesh({ scale = 1, palette = 0 }) {
  const tips = useMemo(() => {
    const sets = [
      [
        { pos: [0.55, 0.32, 0.18], color: ATOM_LIME, r: 0.2 },
        { pos: [-0.48, 0.28, 0.22], color: ATOM_AQUA, r: 0.18 },
        { pos: [0.12, -0.52, 0.2], color: ATOM_LIME, r: 0.17 },
        { pos: [-0.1, 0.15, -0.55], color: ATOM_BLUE, r: 0.19 },
        { pos: [0.42, -0.18, -0.35], color: ATOM_AQUA, r: 0.16 },
      ],
      [
        { pos: [0.5, 0.4, 0], color: ATOM_BLUE, r: 0.18 },
        { pos: [-0.5, 0.35, 0.15], color: ATOM_LIME, r: 0.17 },
        { pos: [0, -0.5, 0.25], color: ATOM_AQUA, r: 0.2 },
        { pos: [0.2, 0.1, -0.52], color: ATOM_LIME, r: 0.16 },
      ],
      [
        { pos: [0.48, 0.25, 0.3], color: ATOM_AQUA, r: 0.17 },
        { pos: [-0.4, 0.4, -0.1], color: ATOM_LIME, r: 0.19 },
        { pos: [0.15, -0.45, -0.25], color: ATOM_BLUE, r: 0.18 },
        { pos: [-0.3, -0.2, 0.48], color: ATOM_AQUA, r: 0.16 },
        { pos: [0.35, 0.05, -0.45], color: ATOM_LIME, r: 0.15 },
        { pos: [-0.05, 0.5, 0.2], color: ATOM_BLUE, r: 0.14 },
      ],
    ]
    return sets[palette % sets.length]
  }, [palette])

  const coreColor = palette === 1 ? ATOM_BLUE : ATOM_AQUA

  return (
    <group scale={scale}>
      <mesh>
        <sphereGeometry args={[0.32, 28, 28]} />
        <AtomMaterial color={coreColor} emissiveIntensity={0.45} />
      </mesh>
      {tips.map((tip, i) => {
        const mid = [tip.pos[0] * 0.5, tip.pos[1] * 0.5, tip.pos[2] * 0.5]
        const length = Math.hypot(tip.pos[0], tip.pos[1], tip.pos[2]) * 0.72
        return (
          <group key={i}>
            <mesh position={mid} quaternion={bondQuaternion(tip.pos)}>
              <cylinderGeometry args={[0.045, 0.045, length, 8]} />
              <meshStandardMaterial color={BOND} roughness={0.4} metalness={0.1} />
            </mesh>
            <mesh position={tip.pos}>
              <sphereGeometry args={[tip.r, 20, 20]} />
              <AtomMaterial color={tip.color} />
            </mesh>
          </group>
        )
      })}
    </group>
  )
}

function FieldMolecules({ progress }) {
  const group = useRef()
  const layout = useMemo(() => makeFieldLayout(26), [])
  const clear = smooth(BEATS.clearStart, BEATS.clearEnd, progress)
  const focus = smooth(BEATS.focusStart, BEATS.focusEnd, progress)

  useFrame((state) => {
    if (!group.current) return
    const t = state.clock.elapsedTime
    const fade = (1 - focus * 0.35) * (1 - clear)

    group.current.children.forEach((child, i) => {
      const item = layout[i]
      if (!item) return
      const bob = Math.sin(t * item.drift + item.phase) * 0.12
      const driftX = Math.cos(t * item.drift * 0.6 + item.phase) * 0.08
      child.position.set(item.position[0] + driftX, item.position[1] + bob, item.position[2])
      child.rotation.x = item.rotation[0] + t * 0.08 * item.drift
      child.rotation.y = item.rotation[1] + t * 0.12 * item.drift
      child.visible = fade > 0.03
      // Soften via scale rather than fighting material opacity every frame
      child.scale.setScalar(item.scale * (0.55 + fade * 0.45))
    })
    group.current.visible = fade > 0.03
  })

  return (
    <group ref={group}>
      {layout.map((item, i) => (
        <group key={i} position={item.position} scale={item.scale}>
          <MoleculeMesh palette={item.palette} />
        </group>
      ))}
    </group>
  )
}

function HeroMolecule({ progress }) {
  const root = useRef()

  useFrame((state, delta) => {
    if (!root.current) return
    const t = state.clock.elapsedTime
    const focus = smooth(BEATS.focusStart, BEATS.focusEnd, progress)
    const transit = smooth(BEATS.transitStart, BEATS.transitEnd, progress)
    const brand = smooth(BEATS.brandStart, BEATS.brandEnd, progress)

    if (progress < BEATS.transitStart) {
      // Float above the membrane plane, then lock to center over the pore
      heroTarget.set(
        lerp(2.1, 0, focus) + Math.sin(t * 0.5) * 0.06 * (1 - focus),
        lerp(1.4, 1.8, focus) + Math.cos(t * 0.65) * 0.05 * (1 - focus),
        lerp(1.0, 0.2, focus),
      )
    } else if (progress < BEATS.poreOutEnd) {
      // Drop vertically through the horizontal nanopore (Y axis)
      heroTarget.set(0, lerp(1.8, -2.2, transit), 0.15)
    } else {
      // Settle into the Q of AAGAMISEQ
      heroTarget.set(lerp(0, 1.55, brand), lerp(-2.2, 0.05, brand), lerp(0.15, 0.2, brand))
    }

    root.current.position.lerp(heroTarget, 1 - Math.exp(-delta * 7))
    root.current.rotation.x += delta * (0.35 + focus * 0.2)
    root.current.rotation.y += delta * (0.55 + transit * 0.25)

    const size = lerp(0.85, 1.25, focus) * lerp(1, 0.78, transit * 0.35) * lerp(1, 0.42, brand)
    root.current.scale.setScalar(size)
  })

  return (
    <group ref={root}>
      <MoleculeMesh palette={0} />
    </group>
  )
}

/** Flat horizontal membrane with a circular aperture — Agami-style nanopore sheet */
function Nanopore({ progress }) {
  const group = useRef()
  const sheet = useRef()
  const rim = useRef()
  const glow = useRef()

  const visible =
    smooth(BEATS.poreInStart, BEATS.poreInEnd, progress) * (1 - smooth(BEATS.poreOutStart, BEATS.poreOutEnd, progress))

  const nodes = useMemo(() => {
    const list = []
    for (let i = 0; i < 56; i += 1) {
      const a = (i / 56) * Math.PI * 2 + seededRandom(i) * 0.2
      const r = 1.35 + seededRandom(i + 3) * 3.4
      list.push([Math.cos(a) * r, 0.02, Math.sin(a) * r])
    }
    // Fill a few interior lattice points on the sheet (outside the pore)
    for (let i = 0; i < 24; i += 1) {
      const x = (seededRandom(i + 50) - 0.5) * 8
      const z = (seededRandom(i + 80) - 0.5) * 8
      if (Math.hypot(x, z) < 1.2) continue
      list.push([x, 0.015, z])
    }
    return list
  }, [])

  useFrame((state, delta) => {
    if (!group.current) return
    const pulse = 1 + Math.sin(state.clock.elapsedTime * 1.5) * 0.012
    poreScale.set(pulse, 1, pulse)
    group.current.scale.lerp(poreScale, 1 - Math.exp(-delta * 5))
    group.current.visible = visible > 0.01
    if (sheet.current) {
      sheet.current.opacity = visible * 0.82
      sheet.current.transparent = true
    }
    if (rim.current) rim.current.opacity = visible
    if (glow.current) glow.current.opacity = visible * 0.45
  })

  return (
    <group ref={group} position={[0, 0, 0]} rotation={[0, 0, 0]}>
      {/* Horizontal membrane sheet (XZ plane) with central circular aperture */}
      <mesh rotation={[-Math.PI / 2, 0, 0]}>
        <ringGeometry args={[1.05, 5.5, 128]} />
        <meshStandardMaterial
          ref={sheet}
          color="#6eb8b0"
          emissive="#1f5c58"
          emissiveIntensity={0.2}
          metalness={0.3}
          roughness={0.42}
          transparent
          side={THREE.DoubleSide}
          depthWrite={false}
        />
      </mesh>

      {/* Slight thickness band on the pore edge */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0.01, 0]}>
        <ringGeometry args={[1.02, 1.18, 96]} />
        <meshStandardMaterial
          ref={rim}
          color="#5fdad1"
          emissive="#3ecfc0"
          emissiveIntensity={1.6}
          metalness={0.35}
          roughness={0.22}
          transparent
          side={THREE.DoubleSide}
        />
      </mesh>

      {/* Soft horizontal glow line around the aperture */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.01, 0]}>
        <ringGeometry args={[1.15, 1.55, 96]} />
        <meshBasicMaterial ref={glow} color="#7ef0e4" transparent side={THREE.DoubleSide} depthWrite={false} />
      </mesh>

      {/* Lattice atoms on the membrane surface — reads as a thin sheet, not a vortex */}
      {nodes.map((pos, i) => (
        <mesh key={i} position={pos}>
          <sphereGeometry args={[0.04 + seededRandom(i) * 0.025, 8, 8]} />
          <meshStandardMaterial color="#9fd4ce" emissive="#3a8a84" emissiveIntensity={0.15} roughness={0.4} />
        </mesh>
      ))}
    </group>
  )
}

function MicroParticles({ progress }) {
  const points = useRef()
  const data = useRef(null)
  const clear = smooth(BEATS.clearStart, BEATS.clearEnd, progress)

  if (!data.current) {
    const count = 360
    const positions = new Float32Array(count * 3)
    const colors = new Float32Array(count * 3)
    const seeds = new Float32Array(count)
    const palette = [new THREE.Color('#b7fff0'), new THREE.Color('#5fdad1'), new THREE.Color('#9ad0ff')]
    for (let i = 0; i < count; i += 1) {
      const o = i * 3
      positions[o] = THREE.MathUtils.randFloatSpread(16)
      positions[o + 1] = THREE.MathUtils.randFloatSpread(9)
      positions[o + 2] = THREE.MathUtils.randFloat(-5, 4)
      seeds[i] = Math.random()
      const c = palette[i % palette.length]
      colors[o] = c.r
      colors[o + 1] = c.g
      colors[o + 2] = c.b
    }
    const geometry = new THREE.BufferGeometry()
    geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3))
    geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    data.current = { geometry, seeds, count }
  }

  useFrame((state) => {
    if (!points.current || !data.current) return
    const positions = data.current.geometry.attributes.position.array
    const { seeds, count } = data.current
    const t = state.clock.elapsedTime
    const opacity = 0.35 * (1 - clear)

    for (let i = 0; i < count; i += 1) {
      const o = i * 3
      const s = seeds[i]
      positions[o] += 0.0008 + s * 0.0012
      positions[o + 1] += Math.sin(t * (0.15 + s * 0.2) + s * 10) * 0.0007
      if (positions[o] > 8) positions[o] = -8
    }
    data.current.geometry.attributes.position.needsUpdate = true
    points.current.material.opacity = opacity
    points.current.visible = opacity > 0.02
  })

  return (
    <points ref={points} geometry={data.current.geometry}>
      <pointsMaterial
        vertexColors
        size={0.05}
        sizeAttenuation
        transparent
        opacity={0.35}
        depthWrite={false}
        blending={THREE.AdditiveBlending}
      />
    </points>
  )
}
